#include <Arduino.h>
#include <Servo.h>
Servo servo1;
const int POT1_PIN = A3;  
const int POT2_PIN = A4;  
const int POT3_PIN = A5;  
const int SERVO_PIN = 2;  

void setup();
void loop();
void setup() {
  servo1.attach(SERVO_PIN);
  servo1.write(0); 
}
void loop() {
  int pot1Value = analogRead(POT1_PIN);
  int pot2Value = analogRead(POT2_PIN);
  int pot3Value = analogRead(POT3_PIN);
  int minAngle = map(pot1Value, 0, 1023, 0, 90);
  int maxAngle = map(pot2Value, 0, 1023, 90, 180);
  int currentAngle = map(pot3Value, 0, 1023, minAngle, maxAngle);
  servo1.write(currentAngle);
  delay(20); 
}
